      "glvm.continuity.diagram.processB": "PROCESO B",
      "glvm.continuity.diagram.ready": "LISTO",
      "glvm.continuity.diagram.resume": "REANUDAR",
      "glvm.continuity.diagram.roadmap": "HOJA DE RUTA",
