      "home.sections.6.demos.1.label": "btc-median.tox",
      "home.sections.6.demos.1.lanes.0": "BINANCE",
      "home.sections.6.demos.1.lanes.1": "COINBASE",
      "home.sections.6.demos.1.lanes.2": "KRAKEN",
