      "home.sections.6.demos.3.label": "装有 1 ALUX 的钱包",
      "home.sections.6.demos.3.rows.0.0": "Alice",
      "home.sections.6.demos.3.rows.0.1": "10天内使用",
      "home.sections.6.demos.3.rows.1.0": "Bob",
      "home.sections.6.demos.3.rows.1.1": "仅限购书",
      "home.sections.6.demos.3.rows.2.0": "Carole",
